functions.ghostToken:
function ghostToken(){
  if(!GH_SHARE) return '';                                                  // the off arm cannot even read the bearer slot
  if(ghostTokenValid(_ghostToken)) return _ghostToken;
  let prior=''; try{ prior=localStorage.getItem(GH_TOKEN_KEY)||''; }catch(e){ return ''; }
  if(ghostTokenValid(prior)) return _ghostToken=prior;
  try{
    const c=globalThis.crypto; if(!c || typeof c.getRandomValues!=='function') return '';
    const bytes=new Uint8Array(GH_TOKEN_BYTES); c.getRandomValues(bytes); let token='';
    for(let i=0;i<bytes.length;i++) token+=bytes[i].toString(16).padStart(2,'0');
    if(!ghostTokenValid(token)) return '';
    localStorage.setItem(GH_TOKEN_KEY,token); _ghostToken=token; return token;
  }catch(e){ return ''; }
}

functions.ghostLonBucket:
function ghostLonBucket(offsetMinutes){
  // Privacy decision: the relay gets the timezone's coarse UTC offset only. Geolocation and the observer longitude never enter this path.
  let offset=Number(offsetMinutes);
  if(!Number.isFinite(offset)) try{ offset=new Date().getTimezoneOffset(); }catch(e){ offset=0; }
  const hour=Math.round(-offset/GH_MINUTES_PER_HOUR);
  return ((hour+GH_LON_SHIFT)%GH_LON_BUCKETS+GH_LON_BUCKETS)%GH_LON_BUCKETS;
}

functions.ghostRelayUrl:
function ghostRelayUrl(path){
  if(!GH_SHARE) return '';
  const raw=CFG.skyDay&&typeof CFG.skyDay.api==='string'?CFG.skyDay.api.replace(/\/+$/,''):'';
  return raw && /^https?:\/\//i.test(raw)?raw+path:'';
}

functions.ghostRelayFetch:
async function ghostRelayFetch(path,init,consume){
  if(!GH_SHARE || typeof fetch!=='function') return null;
  const url=ghostRelayUrl(path); if(!url) return null;
  const ctl=typeof AbortController!=='undefined'?new AbortController():null;
  let timer=null;
  const timeout=new Promise(resolve=>{ timer=setTimeout(()=>{ if(ctl) ctl.abort(); resolve(null); },GH_FETCH_TIMEOUT_MS); });
  const request=(async()=>{ try{ const response=await fetch(url,ctl?Object.assign({},init||{},{signal:ctl.signal}):(init||{})); return typeof consume==='function'?await consume(response):response; }catch(e){ return null; } })();
  try{ return await Promise.race([request,timeout]); }finally{ clearTimeout(timer); }
}

functions.ghostUtf8Bytes:
function ghostUtf8Bytes(text){
  let bytes=0;
  for(let i=0;i<text.length;i++){
    const code=text.charCodeAt(i);
    if(code<0x80) bytes++;
    else if(code<0x800) bytes+=2;
    else if(code>=0xd800 && code<=0xdbff && i+1<text.length && text.charCodeAt(i+1)>=0xdc00 && text.charCodeAt(i+1)<=0xdfff){ bytes+=4; i++; }
    else bytes+=3;
  }
  return bytes;
}

functions.ghostRelayJson:
async function ghostRelayJson(path,init,maxBytes){
  const limit=Number.isSafeInteger(maxBytes)?Math.max(GH_MAX_BYTES,Math.min(GH_GHOSTS_RESPONSE_MAX,maxBytes)):GH_MAX_BYTES;
  return ghostRelayFetch(path,init,async response=>{
    if(!response || !response.ok) return null;
    const declared=response.headers&&typeof response.headers.get==='function'?response.headers.get('content-length'):null;
    if(declared!==null && declared!==''){
      const bytes=Number(declared);
      if(!Number.isSafeInteger(bytes) || bytes<0 || bytes>limit) return null;
    }
    let text='';
    if(response.body && typeof response.body.getReader==='function' && typeof TextDecoder!=='undefined'){
      const reader=response.body.getReader(), decoder=new TextDecoder(), pieces=[]; let bytes=0;
      for(;;){
        const part=await reader.read(); if(part.done) break;
        if(!part.value || !Number.isSafeInteger(part.value.byteLength)) return null;
        bytes+=part.value.byteLength; if(bytes>limit){ try{ reader.cancel(); }catch(e){} return null; }
        pieces.push(decoder.decode(part.value,{stream:true}));
      }
      pieces.push(decoder.decode()); text=pieces.join('');
    }else{
      if(typeof response.text!=='function') return null;
      text=await response.text(); if(typeof text!=='string' || ghostUtf8Bytes(text)>limit) return null;
    }
    const value=JSON.parse(text); return ghostSerializedBytes(value)<=limit?value:null;
  });
}

functions.ghostUploadAttempt:
async function ghostUploadAttempt(token,bucket,artifact,pageExit){
  const body=JSON.stringify({lonBucket:bucket,artifact:artifact});
  const init={method:'POST',headers:ghostRelayHeaders(token,true),body:body};
  // An oversized page-exit body deliberately uses ordinary best-effort fetch: keepalive would be rejected, while a normal Bow must never inherit unload constraints.
  if(pageExit===true && ghostUtf8Bytes(body)<=GH_KEEPALIVE_BUDGET) init.keepalive=true;
  const response=await ghostRelayFetch(GH_GHOST_PATH,init);
  return !!(response&&response.ok);
}

functions.ghostShareUpload:
function ghostShareUpload(artifact,pageExit){
  if(!GH_SHARE || !artifact) return;
  const token=ghostToken(); if(!token) return;
  const bucket=ghostLonBucket();
  ghostUploadAttempt(token,bucket,artifact,pageExit===true).then(ok=>{ if(!ok) setTimeout(()=>{ ghostUploadRetry(token,bucket,artifact); },GH_UPLOAD_RETRY_MS); },()=>{ setTimeout(()=>{ ghostUploadRetry(token,bucket,artifact); },GH_UPLOAD_RETRY_MS); });
}

functions.ghostArtifactValid:
function ghostArtifactValid(value){
  if(!value || typeof value!=='object') return null;
  const keys=Object.keys(value);
  if(keys.length!==GH_V1_KEYS.length) return null;
  for(const key of keys) if(GH_V1_KEYS.indexOf(key)<0) return null;
  if(value.v!==GH_VERSION || !realCivilDate(value.date)) return null;
  if(!Number.isInteger(value.moonBucket) || value.moonBucket<0 || value.moonBucket>7 || !Number.isFinite(value.bpm0) || value.bpm0<1 || value.bpm0>400 || !Number.isFinite(value.dur) || value.dur<GH_WORTHY_DUR || value.dur>86400) return null;
  if(!Array.isArray(value.bpmCurve) || !Array.isArray(value.targets) || !Array.isArray(value.taps) || !Array.isArray(value.fires)) return null;
  if(value.bpmCurve.length>GH_CAP_BPM || value.targets.length>GH_CAP_TARGETS || value.taps.length>GH_CAP_TAPS || value.fires.length>GH_CAP_FIRES) return null;
  let prior=-1;
  for(const row of value.bpmCurve){ if(!Array.isArray(row)||row.length!==2||!Number.isFinite(row[0])||row[0]<prior||row[0]<0||row[0]>value.dur||!Number.isFinite(row[1])||row[1]<1||row[1]>400) return null; prior=row[0]; }
  prior=-1; let priorSlot=-1;
  for(const row of value.targets){
    if(!Array.isArray(row)||row.length!==6||!Number.isFinite(row[0])||row[0]<prior||row[0]<0||row[0]>value.dur||!Number.isInteger(row[1])||row[1]<0||row[1]>3||!Number.isSafeInteger(row[2])||row[2]<=priorSlot||!Number.isFinite(row[3])||row[3]<row[0]||row[3]>value.dur+60||(row[4]!==0&&row[4]!==1)) return null;
    if(row[4]===1 && (!Number.isFinite(row[5])||row[5]<row[0]||row[5]>row[3]||row[5]>value.dur)) return null;
    if(row[4]===0 && row[5]!==null) return null;
    prior=row[0]; priorSlot=row[2];
  }
  prior=-1;
  for(const row of value.taps){ if(!Array.isArray(row)||row.length!==3||!Number.isFinite(row[0])||row[0]<prior||row[0]<0||row[0]>value.dur||!Number.isInteger(row[1])||row[1]<0||row[1]>3||!Number.isInteger(row[2])||row[2]<-1||row[2]>100) return null; prior=row[0]; }
  prior=-1;
  for(const row of value.fires){ if(!Array.isArray(row)||row.length!==4||!Number.isFinite(row[0])||row[0]<prior||row[0]<0||row[0]>value.dur||!Number.isFinite(row[1])||Math.abs(row[1])>GH_AIM_YAW_MAX||!Number.isFinite(row[2])||Math.abs(row[2])>GH_AIM_PITCH_MAX||(row[3]!==0&&row[3]!==1)) return null; prior=row[0]; }
  return value;
}

functions.ghostMailValid:
function ghostMailValid(value,dur){
  if(!Array.isArray(value) || value.length>GH_CAP_MAIL) return null;
  let prior=-1;
  for(const row of value){
    if(!Array.isArray(row) || row.length!==2 || !Number.isFinite(row[0]) || row[0]<prior || row[0]<0 || row[0]>dur || !Number.isInteger(row[1]) || row[1]<0 || row[1]>3) return null;
    prior=row[0];
  }
  return value;
}

functions.ghostWrapperValid:
function ghostWrapperValid(value){
  if(!value || typeof value!=='object') return null;
  const keys=Object.keys(value);
  if(keys.length!==GH_WRAPPER_KEYS.length) return null;
  for(const key of keys) if(GH_WRAPPER_KEYS.indexOf(key)<0) return null;
  const ghost=ghostArtifactValid(value.ghost);
  if(!ghost || !ghostMailValid(value.mail,ghost.dur)) return null;
  return value;
}

functions.ghostMoonSigil:
function ghostMoonSigil(bucket){
  if(!Number.isInteger(bucket) || bucket<0 || bucket>7) return '';
  const at=bucket*GH_SIGIL_CODE_UNITS; return GH_MOON_SIGILS.slice(at,at+GH_SIGIL_CODE_UNITS);
}

functions.ghostMailAttempt:
async function ghostMailAttempt(token,toId,catches){
  const response=await ghostRelayFetch(GH_MAIL_PATH,{method:'POST',headers:ghostRelayHeaders(token,true),body:JSON.stringify({toId:toId,catches:catches})});
  return !!(response&&response.ok);
}
